#include <cstdio>
#include <fstream>
#include <iostream>
#include <string>
using namespace std;

int main() {
    ofstream out("marks.txt");
    out << "Asha 91 Ravi 78 Mia 85";
    out.close();

    ifstream in("marks.txt");
    string name;
    int mark = 0;
    int total = 0;
    while (in >> name >> mark) {
        total += mark;
    }
    cout << total << endl;
    in.close();
    remove("marks.txt");
    return 0;
}

