#include <fstream>
#include <iostream>
#include <string>
using namespace std;

int main() {
    ifstream in("missing_file.txt");
    if (!in.is_open()) {
        cout << "Cannot open missing_file.txt" << endl;
        return 0;
    }
    string line;
    getline(in, line);
    cout << "First line: " << line << endl;
    return 0;
}

